// A renderer lease belongs to one main-process lifetime; permanent manual epochs outlive it.
const PROCESS_LEASE_OWNER=`${process.pid}:${randomUUID()}`;
export const GENERATION_SCHEMA_SQL=`
CREATE TABLE generation_requests(request_id TEXT PRIMARY KEY REFERENCES digest_requests(id),content_id INTEGER NOT NULL,generation INTEGER NOT NULL,scope_revision TEXT NOT NULL,target_json TEXT NOT NULL,state TEXT NOT NULL,input_json TEXT,input_sha TEXT,plan_json TEXT,model_json TEXT,error_json TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,model_attempts INTEGER NOT NULL DEFAULT 0);
CREATE TABLE generation_tasks(id TEXT PRIMARY KEY,request_id TEXT NOT NULL REFERENCES generation_requests(request_id),stage TEXT NOT NULL,chunk_id TEXT NOT NULL,chunk_order INTEGER NOT NULL,state TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,run_id TEXT,input_sha TEXT NOT NULL,result_json TEXT,result_path TEXT,result_sha TEXT,reused INTEGER NOT NULL DEFAULT 0,error_json TEXT,not_before INTEGER NOT NULL DEFAULT 0,UNIQUE(request_id,stage,chunk_id));
CREATE TABLE generation_calls(run_id TEXT PRIMARY KEY,task_id TEXT NOT NULL,request_id TEXT NOT NULL,generation INTEGER NOT NULL,scope_revision TEXT NOT NULL,stage TEXT NOT NULL,config_json TEXT NOT NULL,input_sha TEXT NOT NULL,submitted INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL,started_at INTEGER NOT NULL,finished_at INTEGER,trace_id TEXT);
CREATE TABLE generation_receipts(run_id TEXT PRIMARY KEY,task_id TEXT NOT NULL,json TEXT NOT NULL,sha TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE generation_cache(cache_key TEXT PRIMARY KEY,json TEXT NOT NULL,file_path TEXT NOT NULL,file_sha TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE generation_artifacts(id TEXT PRIMARY KEY,request_id TEXT NOT NULL REFERENCES generation_requests(request_id),content_id INTEGER NOT NULL,json TEXT NOT NULL,target_json TEXT NOT NULL,files_json TEXT NOT NULL,base_path TEXT NOT NULL,candidate INTEGER NOT NULL,installed INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE generation_editor_meta(content_id INTEGER PRIMARY KEY REFERENCES contents(id),workspace_id TEXT NOT NULL,origin TEXT NOT NULL,manual_epoch INTEGER NOT NULL DEFAULT 0);
CREATE TABLE generation_edit_leases(content_id INTEGER NOT NULL,session_id TEXT NOT NULL,dirty INTEGER NOT NULL,touched_at INTEGER NOT NULL,PRIMARY KEY(content_id,session_id));
CREATE TABLE generation_markdown(workspace_id TEXT PRIMARY KEY,draft_revision INTEGER NOT NULL,draft_sha TEXT NOT NULL,state TEXT NOT NULL,artifact_id TEXT,error TEXT);
CREATE TABLE generation_markdown_projections(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,draft_revision INTEGER NOT NULL,draft_sha TEXT NOT NULL,title_sha TEXT NOT NULL,file_path TEXT NOT NULL,file_sha TEXT NOT NULL,refs_json TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE generation_body_refs(workspace_id TEXT NOT NULL,draft_revision INTEGER NOT NULL,draft_sha TEXT NOT NULL,json TEXT NOT NULL,PRIMARY KEY(workspace_id,draft_revision));
CREATE TABLE generation_adoptions(id TEXT PRIMARY KEY,content_id INTEGER NOT NULL,artifact_id TEXT NOT NULL,before_json TEXT NOT NULL,after_json TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE generation_adoption_undos(adoption_id TEXT PRIMARY KEY,content_id INTEGER NOT NULL,restored_json TEXT NOT NULL,created_at INTEGER NOT NULL);
INSERT INTO generation_editor_meta(content_id,workspace_id,origin,manual_epoch) SELECT content_id,id,'human',1 FROM editor_workspaces;
CREATE INDEX generation_queue ON generation_tasks(state,chunk_order);
`;
export function migrateGenerationSchema(db:Database.Database,dataDir:string,options:{failAfterSchema?:boolean}={}):{backup:string|null;migrated:boolean}{
 const version=Number(db.pragma('user_version',{simple:true}));if(version===9)return{backup:null,migrated:false};if(version!==8)throw Error('生成迁移仅接受明确 E3 隔离的 schema 8 副本');asrDirectory(dataDir);
 const backup=path.join(dataDir,`workbench-pre-v9-${Date.now()}-${randomUUID().slice(0,8)}.sqlite`);db.prepare('VACUUM INTO ?').run(backup);
 db.transaction(()=>{db.exec(GENERATION_SCHEMA_SQL);if(options.failAfterSchema)throw Error('injected generation migration failure');db.pragma('user_version=9');db.prepare('INSERT INTO settings(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value').run('generationMigrationBackup',backup);if(db.pragma('integrity_check',{simple:true})!=='ok'||(db.pragma('foreign_key_check') as unknown[]).length)throw Error('生成迁移完整性检查未通过');})();return{backup,migrated:true};
}
function enabled(db:Database.Database):boolean{return !!db.prepare("SELECT 1 FROM sqlite_master WHERE name='generation_editor_meta'").get();}
/** Called only for actual human changes; temporary input protection is separate. */
export function markGenerationManual(db:Database.Database,contentId:number,sessionId?:string,dirty=true):number{
 if(!enabled(db))return 0;const owner=db.prepare('SELECT id FROM editor_workspaces WHERE content_id=?').get(contentId) as Row|undefined;if(!owner)return 0;
 db.prepare("INSERT INTO generation_editor_meta VALUES(?,?,'human',1) ON CONFLICT(content_id) DO UPDATE SET origin='human',manual_epoch=manual_epoch+1").run(contentId,owner.id);
 if(sessionId)db.prepare('INSERT INTO generation_edit_leases VALUES(?,?,?,?) ON CONFLICT(content_id,session_id) DO UPDATE SET dirty=excluded.dirty,touched_at=excluded.touched_at').run(contentId,sessionId,+dirty,Date.now());
 db.prepare("UPDATE generation_markdown SET state='pending',error=NULL WHERE workspace_id=?").run(owner.id);return Number((db.prepare('SELECT manual_epoch FROM generation_editor_meta WHERE content_id=?').get(contentId) as Row).manual_epoch);
}
/** Complete responses that were rejected locally; one automatic retry per chunk is safe. */
const AUTO_RETRY_CODES=['invalid-output','invalid-response','truncated'];
const messages:Record<string,string>={'waiting-extraction':'等待本条固定范围的图片／音视频文字资料','waiting-configuration':'等待生成服务安全配置；未创建其他收藏授权','waiting-model':'等待核实账户实际可用生成模型','waiting-network':'等待生成服务联网','waiting-files':'确切来源版本或本地文件不可用，请恢复该版本或明确重新消化','waiting-content':'全部适用资料提取完成，但没有可整理文字','result-unknown':'调用可能已提交，结果未知；不会自动重发，明确重试可能再次计费','invalid-output':'生成结果未通过结构、覆盖或来源校验，原资料与人工稿保留','disk':'生成成果写入未完成；成功上游和人工稿保留','attempt-limit':'本阶段分块已达到两次调用上限，请检查后明确重新消化','model-attempt-limit':'账户模型核验已达到本请求两次尝试上限，请恢复条件后明确重新消化','cancelled':'已取消本条生成','unauthorized':'生成服务拒绝凭据，请检查安全配置','rate-limit':'生成服务限流，请稍后明确重试','provider-error':'生成服务未完成，请稍后明确重试','input-limit':'来源超过当前模型或本轮分块安全范围，未静默截尾','truncated':'生成响应被截断，未采用为完整正文或导图'};
const errorJSON=(code:string)=>JSON.stringify({code,message:messages[code]??'生成未完成，原资料和人工稿保留'});
const positive=(value:unknown)=>{if(!Number.isSafeInteger(value)||Number(value)<=0)throw Error('收藏身份无效');};
const identity=(value:unknown)=>{if(typeof value!=='string'||!value||value.length>200)throw Error('生成身份无效');};
export interface GenerationCallToken {taskId:string;requestId:string;contentId:number;generation:number;scopeRevisionId:string;runId:string;stage:GenerationStage;chunk:GenerationChunk;input:GenerationFrozenInput;model:GenerationModelSelection;inputSha256:string;organized?:OrganizedDocument;retryFeedback?:GenerationRetryFeedback}
export interface GenerationRepositoryOptions {ocr?:Pick<OcrRepository,'freezePipelineInputs'|'read'>;asr?:Pick<AsrRepository,'freezePipelineInputs'>;maxChunkCodePoints?:number;maxChunkUtf8Bytes?:number}
export type GenerationWireSizer = (input: GenerationFrozenInput, chunk: GenerationChunk, model: GenerationModelSelection) => number;
export interface GenerationDigestProgress {state:GenerationJobState;stages:Record<'organize'|'map'|'markdown',{state:GenerationJobState;total:number;succeeded:number;attempts:number}>;error?:string}
