  // A temporary lease never changes origin, epoch, documents or Markdown state.
  this.db.prepare('INSERT INTO generation_edit_leases VALUES(?,?,1,?) ON CONFLICT(content_id,session_id) DO UPDATE SET dirty=1,touched_at=excluded.touched_at').run(contentId,sessionId,Date.now());
